const G=9.8,N=60,R=1.2,TG=[30,45,18],D=Math.PI/180;
function shot(v,ad){const a=ad*D,vx=v*Math.cos(a),vy=v*Math.sin(a),T=2*vy/G;return{vx,vy,T,d:vx*T,H:vy*vy/(2*G)}}
function pos(s,f){const t=f*s.T;return[s.vx*t,Math.max(0,s.vy*t-G*t*t/2)+R,0]}
function arc(s,f){const n=Math.max(2,Math.round(f*48)),p=[];for(let i=0;i<=n;i++)p.push(pos(s,f*i/n));return p}
function done(s){return s.hits>=3||(s.shots>=10&&!s.fly)}
export function initialState(){return{ti:0,hits:0,shots:0,fly:null,k:0,last:null,prev:null}}
export function reduce({state,event,inputs}){const s=state;
if(event.type==='action'&&event.action==='launch'){if(s.fly||done(s))return s;return{...s,fly:shot(inputs.speed,inputs.angle),k:0,shots:s.shots+1,prev:s.last?s.last.s:s.prev}}
if(event.type==='step'&&s.fly){const k=s.k+1;if(k<N)return{...s,k};const tx=TG[s.ti],miss=s.fly.d-tx,hit=Math.abs(miss)<=1.5;return{...s,k:N,fly:null,last:{s:s.fly,miss,hit,tx},hits:s.hits+(hit?1:0),ti:hit?Math.min(s.ti+1,2):s.ti}}
return s}
export function evaluate({inputs,state}){const s=state,a=inputs.angle*D,th=a-Math.PI/2;
const nodes={pivot:{quaternion:[0,0,Math.sin(th/2),Math.cos(th/2)]},target:{position:[TG[s.ti],0,0]}};
let cur=null,f=1;if(s.fly){cur=s.fly;f=s.k/N}else if(s.last)cur=s.last.s;
nodes.ball={position:cur?pos(cur,f):[4.3*Math.cos(a),R+4.3*Math.sin(a),0]};
nodes.trail=cur?{visible:true,points:arc(cur,f)}:{visible:false};
nodes.ghost=s.prev?{visible:true,points:arc(s.prev,1)}:{visible:false};
const ro={shots:s.shots,hits:s.hits};const L=s.last;
if(L){ro.dist=L.s.d;ro.miss=Math.abs(L.miss);ro.result=L.hit?'Hit':(L.miss<0?'Short':'Long');ro.ftime=L.s.T;ro.height=L.s.H}
let status='playing',msg;
if(s.hits>=3){status='won';msg='All 3 targets hit in '+s.shots+' launches!'}
else if(s.shots>=10&&!s.fly){status='lost';msg='Out of launches: '+s.hits+' of 3 targets hit.'}
else if(s.fly)msg='In flight...';
else if(L)msg=L.hit?'Hit! Next target at '+TG[s.ti]+' m.':(L.miss<0?'Short':'Long')+' by '+Math.abs(L.miss).toFixed(1)+' m. Adjust and launch again.';
else msg='Target at 30 m. Set angle and speed, then Launch.';
return{nodes,readouts:ro,goal:{status,message:msg}}}
